1	import fs from 'node:fs';
2	import path from 'node:path';
3	import crypto from 'node:crypto';
4	import assert from 'node:assert/strict';
5	import {fileURLToPath} from 'node:url';
6	const here=path.dirname(fileURLToPath(import.meta.url));
7	const [label,checkpointName]=process.argv.slice(2);
8	assert(/^[a-z][a-z0-9-]*$/.test(label??''));
9	assert(/^checkpoint-[a-z0-9-]+\.json$/.test(checkpointName??''));
10	const checkpointPath=path.join(here,checkpointName),cp=JSON.parse(fs.readFileSync(checkpointPath));
11	const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
12	const inside=p=>{const rel=path.relative(here,path.resolve(p));assert(rel&&!rel.startsWith('..')&&!path.isAbsolute(rel));};
13	inside(cp.project);inside(cp.main);assert.notEqual(path.resolve(cp.project),path.resolve(cp.main));
14	const bytes=fs.readFileSync(path.join(cp.project,'.writer/state.json')),mainBytes=fs.readFileSync(path.join(cp.main,'.writer/state.json'));
15	assert.equal(sha(bytes),cp.state_sha256);assert.equal(sha(mainBytes),cp.main_state_sha256);
16	const state=JSON.parse(bytes),main=JSON.parse(mainBytes);
17	assert.equal(state.units.length,cp.registered_units);assert.equal(state.revision,cp.revision);assert.equal(main.revision,cp.main_revision);
18	let verified=0;
19	for(const [ref,item] of Object.entries(cp.files)){
20	 const absolute=path.resolve(cp.project,ref),rel=path.relative(cp.project,absolute);assert(rel&&!rel.startsWith('..')&&!path.isAbsolute(rel));
21	 const st=fs.lstatSync(absolute);assert(st.isFile()&&!st.isSymbolicLink());const b=fs.readFileSync(absolute);
22	 assert.equal(b.length,item.bytes,ref);assert.equal(sha(b),item.sha256,ref);verified++;
23	}
24	const receipt={ok:true,at:new Date().toISOString(),label,checkpoint:checkpointName,checkpoint_sha256:sha(fs.readFileSync(checkpointPath)),project:cp.project,main:cp.main,revision:state.revision,main_revision:main.revision,registered_units:state.units.length,state_sha256:sha(bytes),main_state_sha256:sha(mainBytes),verified_files:verified,note:'Read-only byte restoration check before any candidate mutation. Native resume identity is separately checked against public launch/events.'};
25	fs.writeFileSync(path.join(here,`revision-resume-${label}-verification.json`),JSON.stringify(receipt,null,2)+'\n',{flag:'wx'});
26	console.log(JSON.stringify(receipt));
27	

